package com.northstar.crm.web;
import org.springframework.http.*;import org.springframework.security.core.AuthenticationException;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.Map;
@RestControllerAdvice(basePackageClasses=ApiController.class) public class ApiErrorHandler {@ExceptionHandler(AuthenticationException.class)ResponseEntity<Map<String,Object>> auth(AuthenticationException e){return ResponseEntity.status(401).body(Map.of("error","invalid_api_key","timestamp",Instant.now().toString()));}@ExceptionHandler(Exception.class)ResponseEntity<Map<String,Object>> generic(Exception e){return ResponseEntity.status(400).body(Map.of("error","request_failed","message","The request could not be completed","timestamp",Instant.now().toString()));}}
